from cloudkit import *
PRAC = practical('Make your own first VM — on your laptop, and then the same thing in the cloud. Every step shows <b>two ways</b>: clicking in the tool’s window (UI) and typing commands (CLI). Use whichever you like; the result is identical. Screens and versions on your computer may look slightly different.', [
    ('1 · Check that your CPU can virtualize', uicli(
        ['Windows: press [[Ctrl+Shift+Esc]] to open Task Manager.', 'Click [[Performance]] → [[CPU]].', 'Bottom right should say [[Virtualization: Enabled]].', 'If it says Disabled: restart, enter BIOS/UEFI setup, turn on Intel VT-x / AMD SVM, save.'],
        code('bash', 'Linux terminal / Windows PowerShell', 'grep -c -E -w "vmx|svm" /proc/cpuinfo      # Linux: > 0 means supported\n\n# Windows PowerShell:\n(Get-CimInstance Win32_Processor).VirtualizationFirmwareEnabled')),
        'Without these CPU features VirtualBox offers only 32-bit guests or refuses to start a 64-bit VM.'),
    ('2 · Create the VM with VirtualBox', uicli(
        ['Open VirtualBox → click [[New]].', 'Name: <code>tiffingo-lab</code>; ISO Image: choose <code>ubuntu-24.04-live-server-amd64.iso</code>; tick [[Skip Unattended Installation]] if you want to install by hand.', '[[Hardware]]: Base Memory 2048 MB, Processors 2.', '[[Hard Disk]]: Create a virtual hard disk now, 20 GB (leave “Pre-allocate Full Size” unticked = thin disk).', 'Click [[Finish]] → select the VM → [[Start]] and follow the Ubuntu installer.'],
        code('bash', 'terminal (VBoxManage — VirtualBox’s own CLI)', 'VBoxManage createvm --name tiffingo-lab --ostype Ubuntu_64 --register\nVBoxManage modifyvm tiffingo-lab --cpus 2 --memory 2048 --nic1 nat\nVBoxManage createmedium disk --filename tiffingo-lab.vdi --size 20480\nVBoxManage storagectl tiffingo-lab --name SATA --add sata\nVBoxManage storageattach tiffingo-lab --storagectl SATA --port 0 --device 0 \\\n  --type hdd --medium tiffingo-lab.vdi\nVBoxManage storageattach tiffingo-lab --storagectl SATA --port 1 --device 0 \\\n  --type dvddrive --medium ubuntu-24.04-live-server-amd64.iso\nVBoxManage startvm tiffingo-lab')),
        'The UI simply calls the same engine as VBoxManage. “Not pre-allocated” is thin provisioning — the 20 GB file grows only as Ubuntu writes data.'),
    ('3 · Or create it with KVM on Linux', uicli(
        ['Install and open [[Virtual Machine Manager]] (virt-manager).', 'Click [[Create a new virtual machine]] → [[Local install media]] → choose the Ubuntu ISO.', 'Memory 2048, CPUs 2 → disk 20 GB → Name <code>tiffingo-lab</code> → [[Finish]].'],
        code('bash', 'terminal', 'sudo apt install -y qemu-kvm libvirt-daemon-system virtinst virt-manager\nsudo usermod -aG libvirt $USER    # log out and back in\nvirt-install --name tiffingo-lab --memory 2048 --vcpus 2 \\\n  --disk size=20 --cdrom ubuntu-24.04-live-server-amd64.iso --os-variant ubuntu24.04\nvirsh list --all'), ui_label='UI way — virt-manager'),
        'virt-manager and virt-install both talk to libvirt, which drives QEMU + KVM — a Type 1-style hypervisor inside the Linux kernel.'),
    ('4 · Look from inside the guest', uicli(
        ['Windows guest: open Task Manager → [[Performance]] → [[CPU]]: it shows [[Virtual machine: Yes]].', 'Linux desktop guest: [[Settings]] → [[About]] shows the hardware model (e.g. “VirtualBox”).'],
        code('bash', 'terminal inside the VM', "lscpu | grep -E 'Hypervisor vendor|Virtualization type'\nsystemd-detect-virt")),
        'VirtualBox shows “Oracle”/oracle, KVM shows “KVM”/kvm, an EC2 Nitro instance shows “amazon” — the guest knows it is virtual.'),
    ('5 · Take a snapshot and roll back', uicli(
        ['VirtualBox: select the VM → [[Snapshots]] (or the ☰ menu next to it) → [[Take]] → name <code>fresh-install</code>.', 'Break something inside the VM.', 'Power off → select <code>fresh-install</code> → [[Restore]].'],
        code('bash', 'terminal', 'VBoxManage snapshot tiffingo-lab take fresh-install\nVBoxManage snapshot tiffingo-lab restore fresh-install\n\n# KVM:\nvirsh snapshot-create-as tiffingo-lab fresh-install\nvirsh snapshot-revert tiffingo-lab fresh-install')),
        'A snapshot freezes the disk (and optionally memory) so you can experiment safely.'),
    ('6 · The same idea in the cloud: launch a VM on AWS', uicli(
        ['AWS Console → [[EC2]] → [[Instances]] → [[Launch instances]].', 'Name <code>tiffingo-lab</code>; AMI [[Ubuntu Server 24.04 LTS]]; Instance type [[t3.micro]] (Free Tier eligible).', 'Key pair: create or choose one; Network: default VPC, allow SSH from [[My IP]] only.', 'Click [[Launch instance]] → open the instance → note its state [[Running]] and public IP.'],
        code('bash', 'terminal (AWS CLI)', "AMI=$(aws ssm get-parameter \\\n  --name /aws/service/canonical/ubuntu/server/24.04/stable/current/amd64/hvm/ebs-gp3/ami-id \\\n  --query Parameter.Value --output text)\naws ec2 run-instances --image-id $AMI --instance-type t3.micro --key-name my-key \\\n  --tag-specifications 'ResourceType=instance,Tags=[{Key=Name,Value=tiffingo-lab}]'"), ui_label='UI way — AWS Management Console'),
        'You did not install a hypervisor this time — AWS’s Nitro hypervisor did steps 2–3 for you in about a minute. Full EC2 lab: Lesson 2.1.')],
    cleanup='VirtualBox: right-click the VM → [[Remove]] → [[Delete all files]] (CLI: <code>VBoxManage unregistervm tiffingo-lab --delete</code>). KVM: <code>virsh destroy tiffingo-lab; virsh undefine tiffingo-lab --remove-all-storage</code>. AWS: [[Instance state]] → [[Terminate instance]] (CLI: <code>aws ec2 terminate-instances --instance-ids i-…</code>) so it stops billing.'.replace('[[', '<b>').replace(']]', '</b>'))
